const D = { energy: .55, scale: 1, density: .55, speed: 1, tide: .5, haze: .5, hue: 120, x: .4, y: .62, style: 'tidal', act: 'slack', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 120;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];
const NR = 4;                                    // mangrove ranks, 0 = farthest

const STY = {
  // living green mangrove, teal tidal water, warm dappled light
  tidal:     { skT:[120,26,30], skB:[80,30,58], haze:[90,20,60], root:[28,44,20], rootL:[36,40,36],
               leaf:[110,52,32], leafL:[95,58,52], water:[180,40,24], glint:[70,30,88], grain:18, mono:0 },
  // tannin blackwater at dusk, deep greens, moody
  blackwater:{ skT:[196,30,20], skB:[36,34,40], haze:[40,26,42], root:[26,50,14], rootL:[32,44,28],
               leaf:[130,46,20], leafL:[105,54,38], water:[28,50,12], glint:[44,40,70], grain:20, mono:0 },
  // moonlit nocturne, blue-silver
  nocturne:  { skT:[228,44,10], skB:[210,30,28], haze:[212,24,34], root:[220,32,10], rootL:[210,26,24],
               leaf:[180,34,20], leafL:[190,30,38], water:[218,42,10], glint:[200,20,72], grain:14, mono:0 },
  // ABSTRACTED x-ray botanical: root network as white lines on dark, no colour
  xray:      { skT:[190,30,8], skB:[188,24,12], haze:[188,20,14], root:[186,20,82], rootL:[184,14,94],
               leaf:[184,26,60], leafL:[182,18,80], water:[190,26,10], glint:[184,10,98], grain:5, mono:1 },
  // ABSTRACTED sumi ink: silhouette roots + canopy in tonal wash
  ink:       { skT:[30,6,84], skB:[30,4,72], haze:[30,3,78], root:[30,9,20], rootL:[30,6,38],
               leaf:[30,10,30], leafL:[30,7,48], water:[30,5,54], glint:[30,3,88], grain:28, mono:0 }
};
const st = STY[P.style] || STY.tidal;

const en = Math.max(0, Math.min(1, P.energy));
const hz = Math.max(0, Math.min(1, P.haze));
const wy = height * P.y;                          // waterline
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.ranks.forEach(r => r.g.remove()); S.mist.remove(); }
  S.sky = mk(W, H); S.mist = mk(W, H);
  S.rankTop = Math.max(2, Math.ceil(wy + u * .02));   // ranks drawn above water only

  // gloomy canopy sky
  const g = S.sky; g.noStroke();
  const cT = sh(st.skT), cB = sh(st.skB);
  for (let yy = 0; yy < H; yy++) { const c = L3(cT, cB, Math.pow(Math.min(1, yy / Math.max(1, wy)), .8)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }

  const hazeC = sh(st.haze), rootC = sh(st.root), rootL = sh(st.rootL), leafC = sh(st.leaf), leafL = sh(st.leafL);
  const lit = P.x;

  // --- mangrove ranks: nearer = bigger, darker, more root detail ---
  S.ranks = [];
  for (let L = 0; L < NR; L++) {
    const near = L / (NR - 1);
    const haze = (1 - near) * (.55 + .4 * hz);
    const q = mk(W, S.rankTop); q.noStroke();
    const bRoot = L3(rootC, hazeC, haze), bRootL = L3(rootL, hazeC, haze * .8);
    const bLeaf = L3(leafC, hazeC, haze), bLeafL = L3(leafL, hazeC, haze * .8);
    const nt = Math.floor((3 + near * 3) + P.density * (2 + near * 4));
    const rootY = wy + u * .01;                    // roots meet water here
    for (let i = 0; i < nt; i++) {
      const tx = ((i + fr(L * 20 + i)) / nt) * (W + u * .2) - u * .1;
      const th = u * (.22 + fr(L * 20 + i + 3) * .18) * (.5 + near) * P.scale;   // canopy height
      const tw = u * (.02 + fr(L * 20 + i + 5) * .02) * (.4 + near) * P.scale;
      const topY = rootY - th;
      // arching prop roots splaying to the water
      const nr = Math.floor((4 + near * 6) + P.density * 4);
      q.noFill();
      for (let r = 0; r < nr; r++) {
        const side = r % 2 === 0 ? -1 : 1;
        const spread = tw * (1 + (r / nr) * 4) * side;
        const rc = r / nr < lit ? bRootL : bRoot;
        q.strokeWeight(Math.max(.7, tw * (.16 - near * .04)));
        q.stroke(rc[0], rc[1], Math.max(2, rc[2]), 60 + 26 * near);
        q.beginShape();
        const arch = rootY - th * (.2 + fr(L * 20 + i + r + 30) * .25);
        q.vertex(tx + (fr(r) - .5) * tw, arch);
        q.bezierVertex(tx + spread * .5, arch + th * .1, tx + spread, rootY - th * .06, tx + spread, rootY + u * .01);
        q.endShape();
      }
      // trunk
      q.noStroke(); q.fill(bRoot[0], bRoot[1], bRoot[2], 100);
      q.beginShape(); q.vertex(tx - tw / 2, rootY); q.vertex(tx - tw * .4, topY + th * .3);
      q.vertex(tx + tw * .4, topY + th * .3); q.vertex(tx + tw / 2, rootY); q.endShape(q.CLOSE);
      // foliage canopy blob (clustered leaves)
      if (!st.mono) {
        const nl = Math.floor(14 + near * 16);
        for (let l = 0; l < nl; l++) {
          const lx = tx + (fr(l * 3 + i * 7 + 51) - .5) * tw * 4;
          const ly = topY + (fr(l * 3 + i * 7 + 52)) * th * .5;
          const lr = tw * (1 + fr(l * 3 + 53) * 2);
          const c = fr(l) < lit ? bLeafL : bLeaf;
          q.fill(c[0], c[1], Math.max(2, c[2] + (fr(l) - .5) * 12), 60);
          q.ellipse(lx, ly, lr, lr * .8);
        }
      } else {
        // xray: canopy as an open network
        q.stroke(bLeafL[0], bLeafL[1], bLeafL[2], 40); q.strokeWeight(1); q.noFill();
        for (let l = 0; l < 12; l++) { const a = fr(l + i) * 6.28; q.line(tx, topY + th * .2, tx + Math.cos(a) * tw * 3, topY + th * .2 + Math.sin(a) * tw * 2.4); }
        q.noStroke();
      }
    }
    // aerial veil
    q.fill(hazeC[0], hazeC[1] * .8, hazeC[2], haze * 55); q.rect(0, 0, W, S.rankTop);
    S.ranks.push({ g: q, near: near });
  }

  // mist band between ranks (tileable)
  const mC = L3(sh(st.haze), sh(st.skB), .3);
  S.mist.noStroke();
  for (let i = 0; i < 12; i++) {
    const bx = fr(i * 5 + 71) * W, by = wy - u * (.02 + fr(i * 5 + 72) * .5);
    const bw = u * (.4 + fr(i * 5 + 73) * .9), bhh = u * (.04 + fr(i * 5 + 74) * .1);
    for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 4; kk++) {
      S.mist.fill(mC[0], mC[1] * (1 - kk * .1), Math.min(99, mC[2] + kk * 3), 7 * (1 - kk * .2));
      S.mist.ellipse(bx + rep * W, by + kk * bhh * .1, bw * (1 - kk * .1), bhh * (1 - kk * .08));
    }
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 6) + 6) % 6;
const ACT = { slack: { ripple: .6, sway: .5, tide: 1 }, ebb: { ripple: 1, sway: .6, tide: 1 - sec * .03 }, stir: { ripple: 1.4, sway: 1.4, tide: 1 } };
const act = ACT[P.act] || ACT.slack;
const tide = Math.max(.1, Math.min(1, P.tide * act.tide));
const drift = 0.9 * Math.sin(K.t * .18) + 0.5 * Math.sin(K.t * .46 + 1.7) + 0.3 * Math.sin(K.t * .93);

noStroke();
image(S.sky, 0, 0);

// far mist behind ranks
const MW = S.mist.width;
const mx = ((-K.t * u * .004 * P.speed % MW) + MW) % MW;
push(); tint(0, 0, 100, 55); image(S.mist, mx - MW, u * .02); image(S.mist, mx, u * .02); pop();

// ---------------- reflection first (below waterline), then the trees over the sky ----------------
const waterC = sh(st.water);
fill(waterC[0], waterC[1], waterC[2]); rect(0, wy, width, height - wy);

// flipped mangrove ranks as a broken reflection in the water
push();
translate(0, 2 * wy);
scale(1, -1);
for (let L = 0; L < NR; L++) {
  const r = S.ranks[L];
  const sway = Math.sin(K.t * (.2 + L * .05) + L) * u * .01 * (.3 + r.near);
  tint(waterC[0], 40, 70, (30 + 30 * r.near) * tide);
  image(r.g, sway + drift * u * .002, 0);
}
pop();
noTint();
// water bands sliding over the reflection to break it up (the mirror never holds)
noStroke();
const nb = Math.floor(14 + P.density * 16);
for (let i = 0; i < nb; i++) {
  const f = i / nb;
  const yy = wy + f * (height - wy);
  const ph = K.t * (.4 + f * .8) * P.speed * act.ripple;
  const sway = Math.sin(yy * .05 + ph) * u * .01 * (.3 + f);
  fill(waterC[0], waterC[1] * (1 - f * .3), Math.min(99, waterC[2] + 6 + 18 * f), 22 + 26 * f);
  rect(-u * .05 + sway, yy, width + u * .1, (height - wy) / nb * 1.3);
}
// specular glints on the water
const glintC = sh(st.glint);
blendMode(ADD);
for (let i = 0; i < Math.floor(20 + P.density * 30); i++) {
  const f = fr(i * 3 + 91);
  const yy = wy + Math.pow(f, 1.5) * (height - wy);
  const gx = (fr(i * 3 + 92) * width + Math.sin(K.t * (.3 + f) + i) * u * .03) % width;
  const tw = Math.sin(K.t * (.8 + fr(i)) + i) * .5 + .5;
  fill(glintC[0], glintC[1] * .5, glintC[2], (8 + 20 * tw * en) * (.3 + f));
  ellipse(gx, yy, u * .012 * (.4 + f), u * .002);
}
blendMode(BLEND);

// the mangrove ranks over the sky, farthest first (parallax drift)
for (let L = 0; L < NR; L++) {
  const r = S.ranks[L];
  const dx = (drift * .4 + Math.sin(K.t * (.03 + L * .01) + L) * act.sway) * u * .004 * (.3 + r.near);
  image(r.g, dx, Math.sin(K.t * (.02 + L * .006) + L) * u * .001);
}

// near mist
const mx2 = ((-K.t * u * .008 * P.speed % MW) + MW) % MW;
push(); tint(0, 0, 100, 70); image(S.mist, mx2 - MW, u * .06); image(S.mist, mx2, u * .06); pop();

// occasional ripple rings on the water (something moving below)
noFill();
for (let i = 0; i < 4; i++) {
  const life = ((K.t * (.1 + fr(i * 3 + 101) * .08) * P.speed * act.ripple + fr(i * 3 + 102)) % 1);
  const rx = fr(i * 3 + 103) * width, ry = wy + fr(i * 3 + 104) * (height - wy) * .8 + u * .04;
  strokeWeight(Math.max(.6, u * .0016 * (1 - life)));
  stroke(glintC[0], glintC[1] * .5, glintC[2], 30 * (1 - life) * en);
  ellipse(rx, ry, life * u * .2, life * u * .04);
}
noStroke();

// dappled light through the canopy
if (P.style !== 'xray') {
  blendMode(ADD);
  for (let i = 0; i < Math.floor(6 + P.density * 6); i++) {
    const gx = (fr(i * 3 + 111) * width + Math.sin(K.t * (.1 + i * .03) + i) * u * .03);
    const br = .4 + .6 * Math.sin(K.t * (.4 + i * .1) + i);
    fill(sh(st.leafL)[0], 30, 90, (2.5 + 5 * br * en));
    ellipse(gx, wy - u * (.1 + fr(i) * .3), u * .1, u * .1);
  }
  blendMode(BLEND);
}

// grain, vignette, alpha
if (st.grain > 6) {
  const ng2 = Math.floor(st.grain * 5);
  for (let i = 0; i < ng2; i++) {
    const gx = ((fr(i * 3 + 401) * width) + Math.sin(K.t * .01 + i) * u * .002 + width) % width;
    const gy = fr(i * 3 + 402) * height;
    fill(st.water[0], st.water[1] * .4, fr(i * 3 + 403) > .5 ? 90 : 6, 3 + fr(i) * 5);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .05);
  stroke(sh(st.water)[0], st.water[1], 5, 18 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();
if (P.alpha < 1) { fill(sh(st.water)[0], st.water[1] * .5, 5, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
